Ltac blob_at a :=
  lazymatch goal with K : rw_cells _ _ a _ |- _ =>
    let j := fresh "jb" in let K' := fresh "BL" in
    destruct (rw_cells_forget _ _ _ _ K) as [j K']; clear K; cbn [cells_size csize Nat.add length app] in K' end.

(* [comment removed for export] *)
Ltac tr_parked MU WM TAC :=
  repeat (lazymatch goal with
  | K : parked (rw_cells _ _ _ _) |- _ => unpark K; first [tr_keep K over MU WM by TAC | fail 100 "tr_parked: cannot transport" K]
  | K : parked (bytes_at _ _ _ _) |- _ => unpark K; first [tr_keep K over MU WM by TAC | fail 100 "tr_parked: cannot transport" K]
  | _ => fail
  end).

